CREATE TABLE `composite_score_snapshots` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `academic_year` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `class_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `generated_at` datetime(6) NOT NULL,
  `grade` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intellectual_base_score` double DEFAULT NULL,
  `intellectual_extra_score` double DEFAULT NULL,
  `major_id` bigint DEFAULT NULL,
  `major_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moral_base_score` double DEFAULT NULL,
  `moral_extra_score` double DEFAULT NULL,
  `physical_base_score` double DEFAULT NULL,
  `physical_extra_score` double DEFAULT NULL,
  `rank_no` int DEFAULT NULL,
  `scope_owner_id` bigint DEFAULT NULL,
  `scope_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_id` bigint NOT NULL,
  `student_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_no` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_score` double DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by_user_id` bigint DEFAULT NULL,
  `weighted_intellectual_base_score` double DEFAULT NULL,
  `weighted_intellectual_extra_score` double DEFAULT NULL,
  `weighted_moral_base_score` double DEFAULT NULL,
  `weighted_moral_extra_score` double DEFAULT NULL,
  `weighted_physical_base_score` double DEFAULT NULL,
  `weighted_physical_extra_score` double DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11582 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
