  `cert_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `class_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `committee_comment` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `committee_reviewed_at` datetime(6) DEFAULT NULL,
  `committee_reviewer_id` bigint DEFAULT NULL,
  `committee_reviewer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
