  `proof_text` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `return_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `review_stage` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `score_direction` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `score_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_id` bigint NOT NULL,
  `student_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submission_batch_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `submission_end_time` datetime(6) DEFAULT NULL,
  `submission_period_label` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
