  `teacher_reviewer_id` bigint DEFAULT NULL,
  `teacher_reviewer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `teacher_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `template_id` bigint NOT NULL,
  `template_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `withdrawal_comment` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
