DROP TABLE IF EXISTS `weekly_job_recommendations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `weekly_job_recommendations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) DEFAULT NULL,
  `generated_at` datetime(6) DEFAULT NULL,
  `job_title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recruitment_link` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `salary` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `skills` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL,
  `source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `week_end_date` date NOT NULL,
  `week_start_date` date NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_weekly_job_week_start` (`week_start_date`),
  KEY `idx_weekly_job_week_sort` (`week_start_date`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
